import os, requests, time, json, sys
url=os.environ['GALAXY_URL'].rstrip('/')
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
history_id='bbd44e69cb8906b5d5e8e37ddaee5e95'
source='https://cnsgenomics.com/data/giant_2022/GIANT_HEIGHT_YENGO_2022_GWAS_SUMMARY_STATS_HIS.gz'
headers={'x-api-key': key, 'Content-Type':'application/json'}
payload={
  'history_id': history_id,
  'targets': [{
    'destination': {'type':'hdas'},
    'elements': [{
      'src': 'url',
      'url': source,
      'ext': 'tabular',
      'dbkey': '?',
      'name': 'GIANT_HEIGHT_YENGO_2022_GWAS_SUMMARY_STATS_HIS'
    }]
  }]
}
r=requests.post(url+'/api/tools/fetch', headers=headers, json=payload, timeout=60)
print(r.status_code)
print(r.text[:2000])
r.raise_for_status()
j=r.json()
ids=[]
for out in j.get('outputs', []): ids.append(out['id'])
if not ids:
    # newer fetch returns jobs + implicit outputs sometimes
    print(json.dumps(j)[:4000])
    sys.exit(4)
terminal={'ok','error','deleted','discarded','failed_metadata'}
deadline=time.time()+1200
last=None
while True:
    details=[]
    for did in ids:
        d=requests.get(f'{url}/api/histories/{history_id}/contents/{did}', headers={'x-api-key':key}, timeout=30).json()
        details.append({'id':did,'hid':d.get('hid'),'name':d.get('name'),'state':d.get('state'),'extension':d.get('extension'),'file_size':d.get('file_size')})
    states=[x['state'] for x in details]
    if states and all(s in terminal for s in states):
        print(json.dumps({'terminal':details}))
        if any(s"'!='"'ok' for s in states): sys.exit(2)
        break
    cur=','.join(states)
    if cur"'!=last:
        print(json.dumps({'"'states':details}))
        last=cur
    if time.time()>deadline:
        print('timeout', file=sys.stderr); sys.exit(3)
    time.sleep(15)
PY"
